        x = -x
    if b < 0:
        y = -y
    return (x, y)

def find_solution(a, b, n):
    def extended_gcd(a, b):
        if b == 0:
            return a, 1, 0
        g, x1, y1 = extended_gcd(b, a % b)
        return g, y1, x1 - (a // b) * y1

    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        return None
    if a == 0:
        if n % b == 0:
            return (0, n // b)
        return None
    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        return None

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None
    scale = n // g
    x = x0 * scale
    y = y0 * scale
    if a < 0:
        x = -x
    if b < 0:
        y = -y
    return (x, y)

