def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # msis[i] = max sum of increasing subsequence ending at i
    msis = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                msis[i] = max(msis[i], msis[j] + arr[i])

    # msds[i] = max sum of decreasing subsequence starting at i
    msds = arr[:]
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                msds[i] = max(msds[i], msds[j] + arr[i])

    # Combine: for each index i as the peak of the bitonic subsequence
    max_val = 0
    for i in range(n):
        max_val = max(max_val, msis[i] + msds[i] - arr[i])

    return max_val

